// Formato da chave do redis:
// schema:{$schema}:user:$user:perm:$permission
//
// Formato da chave de permissao:
// (mutate|select).$entity[.$action]
//
// Exemplos:
// schema:{app}:user:1:perm:select.user
// schema:{app}:user:1:perm:mutate.user.create


const { schema, permission } = $('Checa Autenticacao').first().json?.data;
const user_id = $('fn-jwt-validation').first().json.payload.sub;

const redis_key = `schema:{${schema}}:user:${user_id}:perm:${permission}`;

return { redis_key };

const { permissionState } = $input.first().json;
const { permission } = $('Checa Autenticacao').first().json.data;
const { payload } = $('fn-jwt-validation').first().json;

if ( permissionState === 'GRANTED' ) {
  return {
    code: 200,
    data: {
      permitido: true,
      payload
    }
  };
}

if ( permissionState === 'DENIED' ) {
  return {
    code: 200,
    data: {
      permitido: false,
      motivo: permission === '*'
          ? `O token de acesso não é mais válido`
          : `Usuáro não tem permissão: ${permission}`,
    }
  };
}

return { code: 300, message: 'Consulte permissões efetivas' };

const { error } = $input.first().json;
return {
  code: 500,
  message: error
};

const { payload, isValid } = $('fn-jwt-validation').first().json;
const { permission } = $('Checa Autenticacao').first().json.data;
return {
  code: 200,
  data: {
    permission,
    isGranted: isValid
  }
}

const input = $input.first().json.body || $input.first().json;
const headers = $input.first().json.headers || {};

// EXTRAÇÃO DO ACCESS TOKEN
//
function getAccessTokenFromCookie(cookieHeader) {
  if (!cookieHeader) return null;
  const cookies = cookieHeader.split(";").reduce((acc, cookie) => {
    const [name, value] = cookie.trim().split("=");
    acc[name] = value;
    return acc;
  }, {});
  return cookies["access_token"] || null;
}

// Busca o token em múltiplas fontes
let access_token = null;

// 1. Checa no payload diretamente
if (input.access_token) {
  access_token = input.access_token;
}
// 2. Tenta pegar do header
else if (headers?.access_token) {
  access_token = headers.access_token;
}
// 3. Tenta pegar dos cookies
else if (headers?.cookie) {
  access_token = getAccessTokenFromCookie(headers.cookie);
}

// EXTRAÇÃO DOS PARÂMETROS
//
let { schema, permission } = input;
let operation = null;
let entity = null;
let action = null;

if (!permission) {
  const { select, mutate, action: inputAction } = input;
  operation = select ? 'select' : mutate ? 'mutate' : null;
  entity = select ?? mutate;
  action = inputAction || null;

  if (!operation || !entity) {
    return {
      code: 400,
      message: 'A operação não foi indicada.'
    };
  }

  permission = action
    ? `${operation}.${entity}.${action}`
    : `${operation}.${entity}`;
} else {
  // Se permission foi fornecida diretamente, extrai as partes dela
  const parts = permission.split('.');
  operation = parts[0] || null;
  entity = parts[1] || null;
  action = parts[2] || null;
}

if (!schema && permission === '*') {
  schema = '*';
} else if (!schema) {
  return {
    code: 400,
    message: 'O schema não foi indicado.'
  };
}

return {
  code: 200,
  data: {
    schema,
    permission,
    access_token
  }
};

// ============================================
// CÓDIGO PARA n8n - Validação de Permissões
// ============================================

// Obter dados do fluxo
const user_roles = $('fn-jwt-validation').first().json.payload.roles;
const requested_permission = $('Checa Autenticacao').first().json.data.permission;

// 1. MAPA DE ROLES (nome → ID)
const available_roles = {
  "Administrador": 1,
  "Candidato": 2,
  "Guardião": 3,
  "Parente": 4,
  "Visitante": 5,
  "Financeiro": 6,
  "Recursos Humanos": 7,
  "Dono da Franquia": 8,
  "Supervisor Assistidos": 9,
  "Supervisor": 10,
  "Suporte": 11,
  "Gerente Comercial": 12,
  "Master": 13
};

// 2. MAPA DE PERMISSÕES
const available_permissions = {
  "*": [1],
  "mutate.aniversariante.*": [8, 9, 13],
  "mutate.assistido.*": [6, 8, 13],
  "mutate.assistido.cadastrar": [6, 8, 13],
  "mutate.assistido.criar": [8, 10, 13],
  "mutate.assistido.listar": [6, 8, 10, 13],
  "mutate.candidato.*": [6, 8, 13],
  "mutate.candidato_assistido.listar": [6, 8, 13],
  "mutate.candidato_contratante.listar": [6, 8, 13],
  "mutate.comercial.*": [6, 8, 12, 13],
  "mutate.controle_ponto.*": [3, 6, 7, 8, 9, 10, 12, 13],
  "mutate.controle_ponto.bater": [3, 6, 7, 8, 9, 10, 12, 13],
  "mutate.escala.*": [8, 13],
  "mutate.escala.gerenciar": [8, 13],
  "mutate.folha_pagamento.importar": [13],
  "mutate.funcionario.*": [6, 7, 8, 12, 13],
  "mutate.funcionario.cadastrar": [6, 7, 8, 12, 13],
  "mutate.funcionario.criar": [6, 7, 8, 12, 13],
  "mutate.funcionario.listar": [6, 7, 8, 12, 13],
  "mutate.guardiao.*": [3, 6, 7, 8, 12, 13],
  "mutate.guardiao.cadastrar": [6, 7, 8, 12, 13],
  "mutate.guardiao.criar": [6, 7, 8, 12, 13],
  "mutate.guardiao.listar": [7, 8, 12, 13],
  "mutate.insumo.*": [6, 8, 13],
  "mutate.insumo.criar": [6, 8, 10, 13],
  "mutate.insumo.listar": [6, 8, 10, 13],
  "mutate.medicamento.*": [6, 8, 10, 13],
  "mutate.medicamento.criar": [6, 8, 10, 13],
  "mutate.medicamento.listar": [6, 8, 10, 13],
  "mutate.plantao.trocar": [3],
  "mutate.proposta.*": [6, 8, 13],
  "mutate.proposta.criar": [6, 8, 13],
  "mutate.proposta.listar": [6, 8, 13],
  "mutate.recursos_humanos.*": [7, 8, 10, 12, 13],
  "mutate.servico.*": [6, 8, 13],
  "mutate.servico.criar": [6, 8, 13],
  "mutate.servico.listar": [6, 8, 13],
  "mutate.treinamento.*": [3],
  "mutate.treinamento_guardiao.*": [3, 8, 13],
  "mutate.treinamento_guardiao.listar": [3, 8, 13],
  "select.aniversariante": [7, 10, 12],
  "select.assistente_cici": [6, 7, 8, 9, 10, 11, 12, 13],
  "select.assistido": [3, 7, 9, 10, 12],
  "select.assistido.cadastro": [3, 7, 9, 10, 12],
  "select.assistido.listar": [3, 7, 9, 10, 12],
  "select.auth": [1, 3, 6, 7, 8, 9, 10, 11, 12, 13],
  "select.dashboard_performance_conduta": [7, 10, 12, 13],
  "select.escala": [3, 7, 9, 10, 12],
  "select.escala.gerenciar": [3, 7, 9, 10, 12],
  "select.guardiao": [9, 10],
  "select.guardiao.listar": [9, 10],
  "select.indicador": [7, 10, 12, 13],
  "select.suporte": [3, 6, 7, 8, 9, 10, 11, 12, 13],
  "select.treinamento_guardiao.listar": [7, 10]
};

// 3. VALIDAÇÃO INICIAL DA PERMISSÃO SOLICITADA
if (!requested_permission || typeof requested_permission !== 'string') {
  return {
    code: 400,
    message: 'Permissão solicitada inválida'
  };
}

// 4. VERIFICAR SE A CHAVE EXATA EXISTE NO JSON DE PERMISSÕES
// Esta verificação é LITERAL - a chave deve existir explicitamente
if (!available_permissions.hasOwnProperty(requested_permission)) {
  return {
    code: 403,
    message: `Permissão '${requested_permission}' não está cadastrada no sistema`
  };
}

// 5. VALIDAÇÕES DOS ROLES DO USUÁRIO
if (!user_roles || !Array.isArray(user_roles) || user_roles.length === 0) {
  return {
    code: 403,
    message: 'Usuário sem papéis definidos'
  };
}

// 6. CONVERTER NOMES DE ROLES → IDs
const user_role_ids = user_roles
  .map(roleName => available_roles[roleName])
  .filter(id => id !== undefined);

if (user_role_ids.length === 0) {
  return {
    code: 403,
    message: 'Nenhum papel válido encontrado para o usuário'
  };
}

// 7. VERIFICAR PERMISSÃO ADMIN TOTAL (*)
if (user_role_ids.includes(1)) {
  const adminRoles = available_permissions["*"];
  if (adminRoles && adminRoles.includes(1)) {
    return {
      code: 200,
      data: { isGranted: true }
    };
  }
}

// 8. BUSCAR PERMISSÃO EXATA
let allowed_role_ids = available_permissions[requested_permission];

// 9. SE NÃO ENCONTROU, TENTAR PERMISSÕES WILDCARD
if (!allowed_role_ids) {
  const parts = requested_permission.split('.');
  for (let i = parts.length - 1; i > 0; i--) {
    const wildcardPermission = parts.slice(0, i).join('.') + '.*';
    if (available_permissions[wildcardPermission]) {
      allowed_role_ids = available_permissions[wildcardPermission];
      break;
    }
  }
}

// 10. VERIFICAR SE ALGUM ROLE DO USUÁRIO TEM PERMISSÃO
const hasPermission = user_role_ids.some(userId => allowed_role_ids.includes(userId));

if (hasPermission) {
  return {
    code: 200,
    data: {
      permission: requested_permission,
      isGranted: true
    }
  };
}

// 11. ACESSO NEGADO
return {
  code: 403,
  message: 'Acesso negado'
};
